const { exec } = require('child_process');
const fs = require('fs');

function runCommand(cmd, opts) {
  return new Promise((resolve, reject) => {
    exec(cmd, opts, (error, stdout, stderr) => {
      if (error) { reject(new Error(error.message + ' | stderr: ' + stderr)); return; }
      resolve(stdout);
    });
  });
}

let output;
try {
  output = await runCommand('claude --print "/daily-briefing"', {
    cwd: 'D:\\segundo-cerebro',
    maxBuffer: 20 * 1024 * 1024,
    timeout: 5 * 60 * 1000
  });
} catch (err) {
  return [{ json: { erro: true, mensagem: err.message } }];
}

const destino = `D:\\segundo-cerebro\\vault\\_sessions\\last-daily-digest-output.txt`;
fs.writeFileSync(destino, output, 'utf8');

return [{ json: { salvo_em: destino, tamanho: output.length } }];
